from tests_src import T, Q2, TF

T(30, "30-7", "The Girl Who Checked the Numbers", "Recount (Historical)", [
"Katherine Johnson was born on the 26th of August 1918 in White Sulphur Springs, a small town in West Virginia, in the United States. From a very young age she loved numbers, and she never stopped counting. \u201cI counted everything,\u201d she remembered later. \u201cI counted the steps to the road, the steps up to church, the number of dishes and silverware I washed.\u201d",
"In June 1953, Katherine began work at a research laboratory at Langley, in Virginia. It later became part of NASA. At that time, a \u201ccomputer\u201d was not a machine but a person who worked out difficult sums by hand. This meant carrying out long calculations again and again, until the answers were certain. Katherine joined a group of clever women who did this job. Because of the rules of the time, the Black women mathematicians at Langley worked in a separate area from their colleagues. Katherine carried on regardless, and she worked with such accuracy that her answers were trusted.",
"As the years passed, her work turned towards space flight. Her task was to calculate a trajectory, the curved path that a spacecraft follows through the sky. In this job, the smallest slip could send a capsule to the wrong place, so every single figure had to be exactly right. Her calculations helped to plan the flight of Alan Shepard. On the 5th of May 1961, he became the first American to travel into space.",
"Soon afterwards, electronic computers began to do much of the arithmetic. The machines were far quicker than any person, but they were new, and not everybody was sure that they could be trusted. In 1962, before the astronaut John Glenn set off to circle the Earth, he asked for Katherine to check the machine\u2019s numbers by hand. His flight took place on the 20th of February 1962, and he became the first American to orbit the Earth. He wanted a person he trusted to look at the numbers first.",
"Katherine worked at Langley for 33 years, until 1986. Her calculations also helped with the Apollo missions, including Apollo 11 in 1969, which carried astronauts to the Moon. She later worked on the Space Shuttle, a spacecraft that could be used again and again. In her later years, she encouraged students to take up science and technology. On the 24th of November 2015, when she was 97 years old, President Barack Obama gave her the Presidential Medal of Freedom. This is the highest honour given to a civilian, which means a person who is not in the armed forces.",
"Katherine Johnson began as a child who could not stop counting. She became a mathematician whose careful work was trusted with some of the most important journeys of her time, and she showed that a person can do great things whatever the rules around them. Her story reminds us that careful, honest work can earn the trust of others.",
], [
 dict(d="2a",k="mc",m=1,q="In paragraph 2, what did the word \u201ccomputer\u201d mean at that time?",opts=["A machine that stored numbers","A person who did sums by hand","A room where engineers met","A tool for flying spacecraft"],a="B"),
 dict(d="2b",k="short",m=1,q="Name one thing Katherine counted when she was a child.",a="Any one of: the steps to the road; the steps up to church; the dishes; the silverware.",g="Accept any one item from her quotation in paragraph 1."),
 dict(d="2b",k="find",m=1,q="Find and copy the words from paragraph 3 that explain what a trajectory is.",a="the curved path that a spacecraft follows through the sky",g="Accept the phrase as copied; \u201ca trajectory\u201d alone is not enough."),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["Katherine began work at Langley in 1953.","In Katherine\u2019s time at Langley, a computer was a machine.","Alan Shepard was the first American to travel into space.","Katherine left Langley in 1962."],a=["T","F","T","F"],g=TF),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened in.",items=["Katherine was given the Presidential Medal of Freedom.","Alan Shepard travelled into space.","Katherine started work at Langley.","John Glenn asked Katherine to check the numbers."],a=[4,2,1,3],g=Q2),
 dict(d="2d",k="short",m=1,q="Why do you think the author begins by telling us that Katherine \u201ccounted everything\u201d as a child?",a="To show that her love of numbers began very early / that she was born to be a mathematician.",g="Accept any answer linking her childhood counting to her later work with numbers."),
 dict(d="2d",k="short",m=2,q="Give two pieces of evidence from the text that other people trusted Katherine\u2019s work.",a="Her answers were trusted at Langley; John Glenn asked for her by name to check the numbers; her calculations were used to plan Alan Shepard\u2019s flight.",g="1 mark for each different piece of evidence. Max 2."),
 dict(d="2d",k="short",m=1,q="In paragraph 4, the text says not everybody was certain that the electronic computers \u201ccould be trusted\u201d. What does John Glenn\u2019s request tell you about how he felt?",a="He was not sure the machines were right / he trusted Katherine\u2019s checking more.",g="Accept: he wanted a person he trusted to check the machine; he had more faith in Katherine than in the new machines."),
 dict(d="2d",k="short",m=2,q="Why do you think John Glenn asked for Katherine, rather than another mathematician? Use the text to explain.",a="She was known for accuracy / her answers were trusted, and she had already helped with Alan Shepard\u2019s flight.",g="1 mark for a sensible reason (trusted, accurate, experienced). 1 mark for supporting evidence from paragraphs 2 or 3."),
 dict(d="2g",k="mc",m=1,q="Why does the author explain that \u201cthe smallest slip could send a capsule to the wrong place\u201d?",opts=["To show why accuracy mattered","To explain how a capsule is built and launched","To make the job sound quick and easy","To describe how far a capsule travels"],a="A"),
 dict(d="2a",k="short",m=1,q="In paragraph 2, Katherine worked \u201cwith such accuracy\u201d. What does \u201caccuracy\u201d mean?",a="Being exactly right / correct and careful.",g="Accept: correctness, being free from mistakes, getting things exactly right."),
 dict(d="2d",k="short",m=2,q="Paragraph 2 says the Black women mathematicians were placed in a separate area. What does the rest of the paragraph show about how Katherine responded? Explain your answer.",a="She carried on and worked so accurately that her answers were trusted; she did not let the separation stop her doing excellent work.",g="1 mark for the idea that she carried on / stayed determined. 1 mark for the supporting detail (she worked with great accuracy and her answers were trusted)."),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up the whole text?",opts=["Katherine\u2019s careful sums helped space flights, and she was honoured for them.","Electronic computers were quicker than people, so they replaced everyone at Langley.","John Glenn was the first person ever to travel into space and to return safely.","Katherine Johnson moved to America to study wind and weather at a laboratory."],a="A"),
 dict(d="2g",k="mc",m=1,q="What is the main purpose of the last paragraph?",opts=["To describe how a spacecraft is built","To compare Katherine with other astronauts","To sum up how Katherine\u2019s life changed","To explain why children should count"],a="C"),
])

T(31, "31-7", "The Doctor of Aldeburgh", "Recount (Historical)", [
"Elizabeth Garrett Anderson was born in London on the 9th of June 1836, at a time when almost every doctor in Britain was a man. Women were expected to look after their homes and families, and the medical schools where doctors were trained did not welcome them. Elizabeth, however, was determined to become a doctor, and she was prepared to be patient and clever in order to succeed.",
"Her first step was to work as a nurse at the Middlesex Hospital in London in 1860. At the same time, she took private lessons in subjects such as Latin, Greek and anatomy, which is the study of the human body. She also applied to several medical schools, but each one turned her away. Many people might have given up at that point, and few would have blamed them. Elizabeth looked instead for another way in.",
"She discovered that a group called the Society of Apothecaries, whose members prepared and sold medicines, set its own examination, and that its rules did not say that only men could take it. If she passed, she would be given a licence to practise as a doctor. In 1865, Elizabeth sat the examination and passed, becoming the first woman to qualify as a doctor in Britain in this openly recognised way. Soon afterwards the Society changed its rules so that other women could not follow the same route, but by then the door had already been opened.",
"A qualified doctor still needed patients, so in 1866 Elizabeth opened a dispensary in London. A dispensary is a place where people can see a doctor and receive medicine, and hers was for women and children. She named it St Mary\u2019s Dispensary for Women and Children. It was a modest beginning, but it gave her the chance to prove, day after day, that a woman could care for patients with skill and kindness.",
"Elizabeth did not want to be the only one. In 1874 she helped to found the London School of Medicine for Women, a place where women could train as doctors without having to search for a loophole, which is a gap in the rules. She served as its dean, or leader, until 1902.",
"In 1902, Elizabeth retired to the seaside town of Aldeburgh, in Suffolk. She did not stop working for her community, however. In 1908 the people of Aldeburgh elected her as their mayor, and she became the first woman to hold that office in England. By then she was married to James Skelton Anderson, whom she had wed in 1871, and she had become known by the name Garrett Anderson. The girl who had once been told that medicine was no place for women had become, in the end, the leader of a whole town.",
], [
 dict(d="2b",k="short",m=1,q="What job did Elizabeth do at the Middlesex Hospital in 1860?",a="She worked as a nurse.",g="Accept nurse / nursing."),
 dict(d="2a",k="mc",m=1,q="In paragraph 3, what is a licence?",opts=["A kind of medicine for fevers","Official permission to do something","A place where new doctors are trained","A test that is very hard to pass"],a="B"),
 dict(d="2b",k="find",m=1,q="Find and copy the phrase from paragraph 4 which explains what a dispensary is.",a="a place where people can see a doctor and receive medicine",g="Accept the phrase as copied."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened in.",items=["Elizabeth opened St Mary\u2019s Dispensary.","Elizabeth became mayor of Aldeburgh.","Elizabeth passed the examination of the Society of Apothecaries.","Elizabeth worked as a nurse at the Middlesex Hospital."],a=[3,4,2,1],g=Q2),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["Elizabeth was accepted by several medical schools.","The Society of Apothecaries\u2019 rules did not say that only men could take its examination.","Elizabeth helped to found a school of medicine for women.","Elizabeth retired to Aldeburgh in 1908."],a=["F","T","T","F"],g=TF),
 dict(d="2d",k="short",m=1,q="Paragraph 1 says Elizabeth was \u201cprepared to be patient and clever\u201d. Give one thing she did later that shows she was clever.",a="She found that the Society of Apothecaries\u2019 examination did not exclude women and took it.",g="Accept any answer about finding another way in / discovering the examination rules."),
 dict(d="2d",k="short",m=2,q="Look at paragraph 2. Why do you think the author says \u201cMany people might have given up at that point\u201d? Explain what this shows about Elizabeth.",a="Being turned away by every medical school was discouraging, but Elizabeth was determined and kept looking for a way.",g="1 mark for the idea that it was discouraging / a good reason to give up. 1 mark for Elizabeth being determined / not giving up."),
 dict(d="2g",k="short",m=1,q="In paragraph 3, the author writes that \u201cthe door had already been opened\u201d. What does this mean?",a="Elizabeth had shown that a woman could qualify as a doctor, so others could follow her example.",g="Accept any answer about Elizabeth making it possible or showing the way for other women, even though the rules changed."),
 dict(d="2d",k="short",m=1,q="What does the text suggest about the size of the dispensary at the start, and how do you know?",a="It was small / modest, because the author calls it \u201ca modest beginning\u201d.",g="1 mark for small or modest, with reference to the phrase. Accept a clear answer without the quotation."),
 dict(d="2d",k="short",m=2,q="Give two ways in which Elizabeth helped other women after she qualified.",a="She cared for women and children at the dispensary; she helped found the London School of Medicine for Women so that women could train as doctors.",g="1 mark for each way. Max 2."),
 dict(d="2a",k="short",m=1,q="In paragraph 5, the text says Elizabeth was the school\u2019s dean. What does \u201cdean\u201d mean here?",a="Leader.",g="Accept leader or head of the school (the text gives the meaning)."),
 dict(d="2g",k="mc",m=1,q="The author ends with the sentence \u201cThe girl who had once been told that medicine was no place for women had become, in the end, the leader of a whole town.\u201d What is the effect of this ending?",opts=["It shows how much her life had changed","It says Elizabeth left medicine for good","It says the town was very small","It makes the story sound frightening"],a="A"),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up paragraphs 1 to 3?",opts=["Elizabeth trained as a nurse in London and stayed a nurse for the rest of her life.","Elizabeth found a way to qualify as a doctor when medical schools would not take her.","Elizabeth changed the rules of the Society of Apothecaries to help other women.","Elizabeth studied Latin and Greek at a university and then became a teacher."],a="B"),
 dict(d="2e",k="short",m=2,q="Elizabeth helped to found a school where women could train as doctors. What do you think might happen in the years after that? Give a prediction and a reason from the text.",a="More women will become doctors, because the school gave them a place to train.",g="1 mark for a sensible prediction (more women doctors / more women in medicine). 1 mark for a reason from paragraph 5."),
])

T(32, "32-7", "A Prize from Sweet Wormwood", "Recount (Historical)", [
"Tu Youyou was born on the 30th of December 1930 in the port city of Ningbo, in the east of China. Years later, she would help to answer an important question that was troubling doctors in many countries: how could a serious disease called malaria be treated more effectively?",
"Malaria is spread by mosquitoes. When one bites a person, it can pass on a tiny living organism called a parasite, which makes the person ill with fevers and chills. In the middle of the twentieth century, the medicines used against malaria were beginning to lose their power, because the parasites had become used to them. Doctors needed a new treatment, and they needed it quickly. Tu\u2019s team belonged to a national research effort known as Project 523.",
"In 1969, Tu was asked to lead a research team in China that would search for one. Rather than start with a laboratory full of chemicals, she began by reading. She and her colleagues studied old medical books and collected traditional recipes, which were often made from plants. By 1971, they had looked at more than two thousand of these recipes and had prepared 380 different plant extracts from about 200 plants. Each extract was tested on mice to see whether it could fight the parasite.",
"Sweet wormwood was one of the plants that caught the team\u2019s attention, but the usual way of preparing plants, which involved heating them, did not bring out its power. Tu did not give up. She returned to the old books and found a clue in a text about 1,600 years old, written by a scholar named Ge Hong. It advised soaking the plant in cold water rather than boiling it. Tu realised that heat might be destroying the very ingredient she was looking for.",
"She changed her method, using a gentler way of extracting the plant\u2019s ingredients at a low temperature. This time the results were striking. In 1972, her team managed to isolate the pure substance, which means to separate it from everything else in the plant. They named it qinghaosu. Today it is known around the world as artemisinin. Medicines based on artemisinin are now used in many parts of the world, and they have helped to treat a great many people with malaria.",
"In 2011, she received the Lasker-DeBakey Clinical Medical Research Award, a major medical prize, and she was the first person from China to do so. In 2015, Tu was awarded the Nobel Prize in Physiology or Medicine, one of the most respected honours in science, which she shared with two other scientists. She was the first woman from mainland China to win a Nobel Prize. Her discovery, which began in old books and was proved in a laboratory, shows how old knowledge and careful modern testing can work side by side.",
], [
 dict(d="2b",k="short",m=1,q="What spreads malaria?",a="Mosquitoes (their bites).",g="Accept mosquitoes / mosquito bites."),
 dict(d="2a",k="mc",m=1,q="In paragraph 2, what is a parasite?",opts=["A tiny living organism that makes a person ill","A kind of plant that is used to make medicine","A machine that is used to find germs in water","A doctor who treats people with fevers"],a="A"),
 dict(d="2b",k="short",m=1,q="In which year did Tu\u2019s team isolate the pure substance qinghaosu?",a="1972.",g="Accept 1972 only."),
 dict(d="2b",k="find",m=1,q="Find and copy the two words from paragraph 4 that name the plant which showed promise.",a="sweet wormwood",g="Accept \u201csweet wormwood\u201d only."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened in.",items=["Tu found the clue about soaking the plant in cold water.","Tu was asked to lead a research team.","Tu was awarded the Nobel Prize.","Tu\u2019s team prepared 380 plant extracts."],a=[3,1,4,2],g=Q2),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["Tu began her search by reading old medical books.","Every extract worked well against the parasite.","Ge Hong\u2019s text advised soaking the plant in cold water.","Tu won the Nobel Prize in 1972."],a=["T","F","T","F"],g=TF),
 dict(d="2b",k="short",m=1,q="In paragraph 2, why did doctors need a new treatment for malaria?",a="The parasites had become used to the old medicines, so those medicines were losing their power.",g="Accept any answer that the old medicines were no longer working well."),
 dict(d="2d",k="short",m=2,q="Paragraph 3 says Tu began \u201cby reading\u201d rather than with \u201ca laboratory full of chemicals\u201d. Why do you think she chose this way to start? Explain your answer.",a="She believed the old books and recipes might already hold useful clues, so studying them would save time and point to the plants most worth testing.",g="1 mark for a sensible reason (old knowledge might contain clues). 1 mark for linking it to the text (recipes, thousands of them, 380 extracts to test)."),
 dict(d="2d",k="short",m=1,q="Tu\u2019s team looked at more than two thousand recipes but prepared only 380 extracts. What does this suggest about how they chose what to test?",a="They picked out the most promising recipes / they did not test all of them.",g="Accept any answer that the team selected or narrowed down the recipes. Do not accept \u201cthey ran out of time\u201d without a link to choosing."),
 dict(d="2g",k="short",m=1,q="In paragraph 5, the author says that this time the results were \u201cstriking\u201d. What does this word suggest about the results?",a="They were impressive / very noticeable / clearly successful.",g="Accept any answer meaning impressive, remarkable or clearly better than before."),
 dict(d="2d",k="short",m=2,q="Give two qualities that helped Tu to succeed. Use evidence from the text for each.",a="Determination: she did not give up when the usual way of preparing sweet wormwood did not work. Careful thinking: she went back to old books and realised heat might destroy the ingredient.",g="1 mark for each quality supported by evidence. Accept persistence, patience, curiosity, cleverness with a matching detail. Max 2."),
 dict(d="2a",k="mc",m=1,q="In paragraph 6, the text says the Nobel Prize is one of the most \u201crespected\u201d honours. What does \u201crespected\u201d mean?",opts=["Very old","Widely admired","Easy to win","Very expensive"],a="B"),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up the whole text?",opts=["Malaria has always been easy to treat with the medicines we have.","Tu Youyou and her team searched old books and plants and found a medicine against malaria.","Scientists should never read old books because they are out of date.","Ge Hong invented artemisinin in 1972 and won a Nobel Prize for it."],a="B"),
 dict(d="2g",k="short",m=2,q="The last sentence says that Tu\u2019s discovery \u201cshows how old knowledge and careful modern testing can work side by side\u201d. Explain what this means, using an example from the text.",a="Old books gave her a clue, and modern testing showed which plant worked; they helped each other.",g="1 mark for explaining the idea (old knowledge and testing combined). 1 mark for an example (Ge Hong\u2019s text / cold-water clue plus testing extracts)."),
])
